 public void Commit(byte[] packet,long frame){if(!NativeRequested)return;int g=BitConverter.ToInt32(packet,176);if(g==0||g!=generation||hero==null)return;if(!active){oldLock=hero.controller.manualLock;oldGravity=hero.hasGravity;oldTouch=hero.hasEntityTouchChecks;oldWeight=hero.baseWeight;oldCollision=hero.collisionMode;oldAlpha=hero.sprAlpha;oldVisible=hero.spr.visible;oldLife=hero.life;oldScarfFront=hero.scarf?.sbFront?.visible??false;oldScarfBack=hero.scarf?.sbBack?.visible??false;bool touch=true;hero.disableAllPhysics(ref touch);hero.controller.manualLock=true;active=true;}
