   CarrierGuard.GuestHitDepth++;try{dc.tool.atk.AttackUtils.Class.hit.Invoke(attack,door);}finally{CarrierGuard.GuestHitDepth--;}
   HostCombat.Instance?.Write("native_dash_breakable_door",frame,hero.__uid,door.__uid,damage,"native AttackUtils.hit / Door.onDie; broken="+door.broken);
