 }
 hero.dx=hero.dy=0;hero.setPosPixel(x*24,y*24);hero.sprAlpha=0;hero.spr.visible=false;if(hero.scarf!=null){if(hero.scarf.sbFront!=null)hero.scarf.sbFront.visible=false;if(hero.scarf.sbBack!=null)hero.scarf.sbBack.visible=false;}
